const _getByNorm = db.prepare('SELECT * FROM bookmarks WHERE url_norm = ? LIMIT 1');
function findByUrl(url) { return hydrate(_getByNorm.get(normalizeUrl(url))); }

const _insBookmark = db.prepare(`
