  if (!name || !String(name).trim()) return res.status(400).json({ error: 'Name is required' });
  const info = db.prepare('INSERT INTO saved_searches (name, query, view, sort) VALUES (?, ?, ?, ?)')
    .run(String(name).trim(), query, view, sort);
