:root {
  --bg: #f6f7f9;
  --surface: #ffffff;
  --surface-2: #f0f2f5;
  --border: #e2e5ea;
  --text: #1c2430;
  --text-dim: #66707e;
  --primary: #3b6ff0;
  --primary-ink: #ffffff;
  --danger: #d64545;
  --star: #f5a623;
  --shadow: 0 1px 3px rgba(20,30,50,.08), 0 6px 18px rgba(20,30,50,.06);
  --radius: 10px;
  --fs: 15px;
}
html[data-theme="dark"] {
  --bg: #12151b;
  --surface: #1b1f27;
  --surface-2: #232833;
  --border: #2c323d;
  --text: #e6e9ef;
  --text-dim: #98a1b0;
  --primary: #5b8cff;
  --primary-ink: #0b1220;
  --danger: #ff6b6b;
  --star: #ffc24b;
  --shadow: 0 1px 3px rgba(0,0,0,.4), 0 8px 24px rgba(0,0,0,.35);
}
html[data-text="small"] { --fs: 13px; }
html[data-text="medium"] { --fs: 15px; }
html[data-text="large"] { --fs: 17px; }

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg); color: var(--text); font-size: var(--fs); line-height: 1.5;
}
button, input, select, textarea { font: inherit; color: inherit; }

.app { display: flex; flex-direction: column; height: 100vh; }

/* Topbar */
.topbar { display: flex; align-items: center; gap: 14px; padding: 10px 16px;
  background: var(--surface); border-bottom: 1px solid var(--border); flex-shrink: 0; }
.brand { font-weight: 700; font-size: 1.05em; white-space: nowrap; }
.brand span { display: inline; }
.search { flex: 1; display: flex; align-items: center; gap: 6px; max-width: 720px; }
.search input { flex: 1; padding: 9px 12px; border: 1px solid var(--border);
  border-radius: 8px; background: var(--surface-2); outline: none; }
.search input:focus { border-color: var(--primary); background: var(--surface); }
.topbar-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }

/* Buttons */
.btn { padding: 8px 14px; border: 1px solid var(--border); background: var(--surface);
  border-radius: 8px; cursor: pointer; white-space: nowrap; transition: background .12s, border-color .12s; }
.btn:hover { background: var(--surface-2); }
.btn.primary { background: var(--primary); color: var(--primary-ink); border-color: transparent; font-weight: 600; }
.btn.primary:hover { filter: brightness(1.06); }
.btn.ghost { background: transparent; }
.btn.danger { color: var(--danger); border-color: color-mix(in srgb, var(--danger) 40%, var(--border)); }
.btn.danger.ghost:hover { background: color-mix(in srgb, var(--danger) 12%, transparent); }
.btn.small { padding: 5px 10px; font-size: .9em; }
.icon-btn { width: 36px; height: 36px; display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid transparent; background: transparent; border-radius: 8px; cursor: pointer; font-size: 1.05em; }
.icon-btn:hover { background: var(--surface-2); }

/* Body layout */
.body { display: flex; flex: 1; min-height: 0; }
.sidebar { width: 230px; flex-shrink: 0; background: var(--surface); border-right: 1px solid var(--border);
  padding: 14px 10px; overflow-y: auto; display: flex; flex-direction: column; gap: 18px; }
.views { display: flex; flex-direction: column; gap: 2px; }
.view-btn { display: flex; align-items: center; gap: 8px; width: 100%; text-align: left;
  padding: 9px 10px; border: none; background: transparent; border-radius: 8px; cursor: pointer; }
.view-btn:hover { background: var(--surface-2); }
.view-btn.active { background: color-mix(in srgb, var(--primary) 15%, transparent); color: var(--primary); font-weight: 600; }
.count { margin-left: auto; font-size: .8em; color: var(--text-dim); background: var(--surface-2);
  padding: 1px 8px; border-radius: 10px; }
.view-btn.active .count { color: var(--primary); }

.side-section { display: flex; flex-direction: column; gap: 6px; }
.side-head { font-size: .78em; text-transform: uppercase; letter-spacing: .05em; color: var(--text-dim);
  padding: 0 8px; font-weight: 700; }
.tag-list, .saved-list { display: flex; flex-direction: column; gap: 1px; }
.tag-item, .saved-item { display: flex; align-items: center; gap: 6px; padding: 6px 8px; border-radius: 7px;
  cursor: pointer; font-size: .95em; }
.tag-item:hover, .saved-item:hover { background: var(--surface-2); }
.tag-item.active { background: color-mix(in srgb, var(--primary) 14%, transparent); color: var(--primary); }
.tag-item .tcount { margin-left: auto; font-size: .82em; color: var(--text-dim); }
.saved-item .del { margin-left: auto; opacity: 0; color: var(--text-dim); border: none; background: none; cursor: pointer; }
.saved-item:hover .del { opacity: 1; }
.empty-mini { color: var(--text-dim); font-size: .88em; padding: 4px 8px; }
.side-footer { margin-top: auto; gap: 8px; }

/* Main */
.main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.toolbar { display: flex; align-items: center; gap: 12px; padding: 10px 18px;
  border-bottom: 1px solid var(--border); background: var(--surface); flex-wrap: wrap; }
.sel-all { display: flex; align-items: center; gap: 7px; cursor: pointer; color: var(--text-dim); font-size: .92em; }
.spacer { flex: 1; }
.sort-wrap { display: flex; align-items: center; gap: 6px; color: var(--text-dim); font-size: .92em; }
.sort-wrap select { padding: 6px 8px; border-radius: 7px; border: 1px solid var(--border); background: var(--surface); }
.bulk-bar { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.sel-count { font-size: .9em; color: var(--text-dim); margin-right: 4px; }

.match-all { margin: 10px 18px 0; padding: 9px 14px; border-radius: 8px; font-size: .92em;
  background: color-mix(in srgb, var(--primary) 12%, transparent); color: var(--primary); }
.match-all a { color: inherit; font-weight: 600; cursor: pointer; text-decoration: underline; }

.list { flex: 1; overflow-y: auto; padding: 12px 18px; display: flex; flex-direction: column; gap: 10px; }

/* Bookmark card */
.card { display: flex; gap: 12px; padding: 12px 14px; background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius); box-shadow: var(--shadow); transition: border-color .12s; }
.card:hover { border-color: color-mix(in srgb, var(--primary) 40%, var(--border)); }
.card.selected { border-color: var(--primary); box-shadow: 0 0 0 1px var(--primary) inset, var(--shadow); }
.card .pick { padding-top: 2px; }
.card .fav { width: 28px; height: 28px; flex-shrink: 0; border-radius: 6px; background: var(--surface-2);
  display: flex; align-items: center; justify-content: center; overflow: hidden; margin-top: 1px; }
.card .fav img { width: 100%; height: 100%; object-fit: contain; }
.card .content { flex: 1; min-width: 0; }
.card .title-row { display: flex; align-items: baseline; gap: 8px; }
.card .title { font-weight: 600; font-size: 1.02em; text-decoration: none; color: var(--text); word-break: break-word; }
.card .title:hover { color: var(--primary); text-decoration: underline; }
.card.is-unread .title::before { content: ""; display: inline-block; width: 8px; height: 8px; border-radius: 50%;
  background: var(--primary); margin-right: 7px; vertical-align: middle; }
.card .url { color: var(--text-dim); font-size: .85em; word-break: break-all; margin: 2px 0 0; }
.card .desc { color: var(--text-dim); font-size: .92em; margin: 6px 0 0; }
.card .meta { display: flex; align-items: center; gap: 8px; margin-top: 8px; flex-wrap: wrap; }
.chip { font-size: .78em; padding: 2px 9px; border-radius: 20px; background: var(--surface-2); color: var(--text-dim);
  cursor: pointer; border: 1px solid var(--border); }
.chip:hover { border-color: var(--primary); color: var(--primary); }
.chip.badge { cursor: default; }
.card .date { font-size: .8em; color: var(--text-dim); margin-left: auto; white-space: nowrap; }
.card .actions { display: flex; flex-direction: column; gap: 4px; align-items: flex-end; }
.card .star { background: none; border: none; cursor: pointer; font-size: 1.15em; color: var(--border); }
.card .star.on { color: var(--star); }
.row-actions { display: flex; gap: 2px; }
.row-actions .icon-btn { width: 30px; height: 30px; font-size: .95em; }

.pager { display: flex; align-items: center; justify-content: center; gap: 12px; padding: 12px; }
.pager button { padding: 6px 12px; }
