cat > /tmp/check.js <<'EOF'
const { chromium } = require('/work/node_modules/playwright');
(async () => {
  const b = await chromium.launch({ args: ['--no-sandbox'] });
  const p = await b.newPage();
  const errs = [];
  p.on('console', m => { if (m.type()==='error') errs.push(m.text()); });
  p.on('pageerror', e => errs.push('PAGEERROR: '+e.message));
  await p.goto('http://127.0.0.1:4000/', { waitUntil: 'networkidle' });
  await p.waitForSelector('#app[data-harness-ready="true"]', { timeout: 8000 });
  const cards = await p.$$eval('.card', els => els.length);
  const ready = await p.getAttribute('#app', 'data-harness-ready');
  await p.screenshot({ path: '/tmp/shot-light.png', fullPage: false });
  // dark mode
  await p.click('#themeBtn');
  await p.screenshot({ path: '/tmp/shot-dark.png' });
  // open add modal
  await p.click('#addBtn');
  await p.waitForSelector('#editModal:not(.hidden)');
  await p.screenshot({ path: '/tmp/shot-modal.png' });
  console.log('ready=%s cards=%d consoleErrors=%j', ready, cards, errs);
  await b.close();
})().catch(e => { console.error('FAIL', e); process.exit(1); });
EOF
PLAYWRIGHT_BROWSERS_PATH=/opt/playwright-browsers node /tmp/check.js

